import itertools, json, datetime
equality = [[-1, 3], [1, -3], [-3, 2], [3, -2]]
inequality = [[-1, 3], [1, -3], [-3, -2], [3, 2]]
projected = {"equality": [[-1, 2], [1, -2]], "inequality": [[-1, -2], [1, 2]]}
def value(cnf, assignment):
    return all(any(assignment[abs(lit)] == int(lit > 0) for lit in clause) for clause in cnf)
tables, work = {}, 0
for name, clauses in [("equality", equality), ("inequality", inequality)]:
    rows = []
    for x, y in itertools.product([0, 1], repeat=2):
        zs = []
        for z in [0, 1]:
            work += 1
            if value(clauses, {1: x, 2: y, 3: z}):
                zs.append(z)
        actual = bool(zs)
        expected = value(projected[name], {1: x, 2: y})
        assert actual == expected
        if actual:
            assert x in zs
        rows.append({"x": x, "y": y, "source_witness_z": zs, "projected_relation": actual})
    tables[name] = rows
marginals = {}
for name, rows in tables.items():
    marginals[name] = {var: sorted({r[var] for r in rows if r["projected_relation"]}) for var in ["x", "y"]}
assert marginals["equality"] == marginals["inequality"] == {"x": [0, 1], "y": [0, 1]}
def resolve_z(clauses):
    positive = [set(c) for c in clauses if 3 in c]
    negative = [set(c) for c in clauses if -3 in c]
    accepted, tautologies = [], 0
    for p in positive:
        for n in negative:
            resolvent = (p - {3}) | (n - {-3})
            if any(-lit in resolvent for lit in resolvent):
                tautologies += 1
            else:
                accepted.append(sorted(resolvent, key=lambda lit: (abs(lit), lit < 0)))
    return sorted(accepted), tautologies
resolution = {}
for name, clauses in [("equality", equality), ("inequality", inequality)]:
    actual, taut = resolve_z(clauses)
    expected = sorted([sorted(c, key=lambda lit: (abs(lit), lit < 0)) for c in projected[name]])
    assert actual == expected and taut == 2
    resolution[name] = {"non_tautological_resolvents": actual, "tautological_resolvents_discarded": taut}
out = {
 "checked_at_utc": datetime.datetime.now(datetime.timezone.utc).isoformat(),
 "scope": "EXACTLY_TWO_EXPLICIT_THREE_VARIABLE_TOY_BLOCKS_ONLY",
 "assignment_evaluations": work,
 "tables": tables,
 "unary_marginals": marginals,
 "resolution": resolution,
 "decoder_for_both": "z := x",
 "external_context": {"formula": "x AND NOT y", "boundary_assignment": [1, 0], "equality_source": "UNSAT", "equality_projected": "UNSAT", "inequality_source": "SAT", "inequality_projected": "SAT", "bad_unary_product_for_equality": "SAT_SPURIOUS"},
 "status": "LOCAL_WORKED_EXAMPLE_CHECK_PASS",
 "trump_runtime_executed": False,
 "independent_verifier_replay": False,
 "generalization": "NONE"
}
print(json.dumps(out, ensure_ascii=False))
